  inline group_type
  read_group_type(xb::xml_reader& reader) {
    group_type result;
    result.name =
        xb::parse<std::string>(reader.attribute_value(xb::qname{"", "name"}));
    {
      auto attr_val__ = reader.attribute_value(xb::qname{"", "count-field"});
      if (!attr_val__.empty()) {
        result.count_field = xb::parse<std::string>(attr_val__);
      }
    }
    {
      auto attr_val__ =
          reader.attribute_value(xb::qname{"", "block-length-field"});
      if (!attr_val__.empty()) {
        result.block_length_field = xb::parse<std::string>(attr_val__);
      }
    }
    auto start_depth = reader.depth();
    while (reader.read()) {
      if (reader.node_type() == xb::xml_node_type::end_element &&
          reader.depth() == start_depth)
        break;
      if (reader.node_type() != xb::xml_node_type::start_element) continue;
      auto& name = reader.name();
      if (name == xb::qname{"http://xb.dev/encoding", "dimension"}) {
        result.dimension = read_dimension_type(reader);
      } else if (name == xb::qname{"http://xb.dev/encoding", "field"}) {
        result.choice.push_back(read_field_type(reader));
      } else if (name == xb::qname{"http://xb.dev/encoding", "padding"}) {
        result.choice.push_back(read_padding_field_type(reader));
      } else if (name == xb::qname{"http://xb.dev/encoding", "constant"}) {
        result.choice.push_back(read_constant_type(reader));
      } else if (name == xb::qname{"http://xb.dev/encoding", "wire-field"}) {
        result.choice.push_back(read_wire_field_type(reader));
      } else if (name == xb::qname{"http://xb.dev/encoding", "group"}) {
        result.choice.push_back(
            std::make_unique<group_type>(read_group_type(reader)));
      } else if (name == xb::qname{"http://xb.dev/encoding", "choice"}) {
        result.choice.push_back(
            std::make_unique<choice_type>(read_choice_type(reader)));
      } else if (name == xb::qname{"http://xb.dev/encoding", "length"}) {
        result.choice.push_back(read_length_type(reader));
      } else if (name == xb::qname{"http://xb.dev/encoding", "discriminant"}) {
        result.choice.push_back(read_discriminant_type(reader));
      } else if (name == xb::qname{"http://xb.dev/encoding", "save-position"}) {
        result.choice.push_back(read_save_position_type(reader));
      } else if (name ==
                 xb::qname{"http://xb.dev/encoding", "computed-field"}) {
        result.choice.push_back(read_computed_field_type(reader));
      } else if (name == xb::qname{"http://xb.dev/encoding", "repeat"}) {
        result.choice.push_back(
            std::make_unique<repeat_type>(read_repeat_type(reader)));
      } else {
        xb::skip_element(reader);
      }
    }
    return result;
  }

