  inline encoding_type
  read_encoding_type(xb::xml_reader& reader) {
    encoding_type result;
    {
      auto attr_val__ =
          reader.attribute_value(xb::qname{"", "target-namespace"});
      if (!attr_val__.empty()) {
        result.target_namespace = xb::parse<std::string>(attr_val__);
      }
    }
    {
      auto attr_val__ = reader.attribute_value(xb::qname{"", "target-schema"});
      if (!attr_val__.empty()) {
        result.target_schema = xb::parse<std::string>(attr_val__);
      }
    }
    auto start_depth = reader.depth();
    while (reader.read()) {
      if (reader.node_type() == xb::xml_node_type::end_element &&
          reader.depth() == start_depth)
        break;
      if (reader.node_type() != xb::xml_node_type::start_element) continue;
      auto& name = reader.name();
      if (name == xb::qname{"http://xb.dev/encoding", "defaults"}) {
        result.defaults = read_defaults_type(reader);
      } else if (name == xb::qname{"http://xb.dev/encoding", "import"}) {
        result.import.push_back(read_import_type(reader));
      } else if (name == xb::qname{"http://xb.dev/encoding", "framing"}) {
        result.choice.push_back(read_framing_type(reader));
      } else if (name == xb::qname{"http://xb.dev/encoding", "frame-stack"}) {
        result.choice.push_back(read_frame_stack_type(reader));
      } else if (name == xb::qname{"http://xb.dev/encoding", "message"}) {
        result.choice.push_back(read_message_type(reader));
      } else {
        xb::skip_element(reader);
      }
    }
    return result;
  }

  inline void
  write_encoding_type(const encoding_type& value, xb::xml_writer& writer) {
    if (value.target_namespace) {
      writer.attribute(xb::qname{"", "target-namespace"},
                       xb::format(*value.target_namespace));
    }
    if (value.target_schema) {
      writer.attribute(xb::qname{"", "target-schema"},
                       xb::format(*value.target_schema));
    }
    if (value.defaults) {
      writer.start_element(xb::qname{"http://xb.dev/encoding", "defaults"});
      write_defaults_type(*value.defaults, writer);
      writer.end_element();
    }
    for (const auto& item : value.import) {
      writer.start_element(xb::qname{"http://xb.dev/encoding", "import"});
      write_import_type(item, writer);
      writer.end_element();
    }
    for (const auto& choice_item : value.choice) {
      std::visit(
          [&](const auto& v) {
            using T = std::decay_t<decltype(v)>;
            if constexpr (std::is_same_v<T, framing_type>) {
              writer.start_element(
                  xb::qname{"http://xb.dev/encoding", "framing"});
              write_framing_type(v, writer);
              writer.end_element();
            } else if constexpr (std::is_same_v<T, frame_stack_type>) {
              writer.start_element(
                  xb::qname{"http://xb.dev/encoding", "frame-stack"});
              write_frame_stack_type(v, writer);
              writer.end_element();
            } else if constexpr (std::is_same_v<T, message_type>) {
              writer.start_element(
                  xb::qname{"http://xb.dev/encoding", "message"});
              write_message_type(v, writer);
              writer.end_element();
            }
          },
          choice_item);
    }
  }

  inline bool
  validate_choice_type(const choice_type& value) {
    return value.alternative.size() >= 1;
  }

  inline bool
  validate_frame_stack_type(const frame_stack_type& value) {
    return value.layer.size() >= 1;
  }

  inline bool
  validate_enum_map_type(const enum_map_type& value) {
    return value.entry.size() >= 1;
  }

  inline bool
  validate_dimension_type(const dimension_type& value) {
    return value.wire_field.size() >= 1;
  }

